import assert from 'node:assert/strict';
export function installGuestExportSession(){const original=globalThis.fetch;globalThis.fetch=async path=>{assert.equal(path,'/api/auth/me','guest export only reads session and must not upload');return new Response(JSON.stringify({error:'请先登录'}),{status:401});};return()=>{globalThis.fetch=original;};}
export async function waitForExport(check){for(let i=0;i<60;i++){if(check())return;await new Promise(resolve=>setImmediate(resolve));}assert.ok(check(),'asynchronous cloud/local export did not finish');}
export function mockArtifactFetch(fallback,{userId='alice',onSave=()=>{}}={}){const files=new Map();return async(path,options={})=>{if(path==='/api/auth/me')return Response.json({user:{id:userId}});if(path==='/api/artifacts'&&options.method==='POST'){const value=JSON.parse(options.body);assert.equal(value.expectedUserId,userId);const bytes=Buffer.from(value.data,'base64'),id='mock-artifact-'+(files.size+1);files.set(id,bytes);onSave(value);return Response.json({item:{id,name:value.name,bytes:bytes.length}},{status:201});}const match=String(path).match(/^\/api\/artifacts\/([^/]+)\/download\?expectedUserId=(.+)$/);if(match){assert.equal(decodeURIComponent(match[2]),userId);return new Response(files.get(match[1]),{headers:{'Content-Type':'application/octet-stream'}});}return fallback(path,options);};}
